const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

// Define the geometry for the Inner Niger Delta (a rough polygon)
// This polygon covers a significant portion of the delta region near Mopti, Mali.
const geometry = ee.Geometry.Polygon(
  [[[-4.5, 13.5],
    [-4.5, 15.5],
    [-2.0, 15.5],
    [-2.0, 13.5],
    [-4.5, 13.5]]]);

// Function to mask clouds from Sentinel-2 SR data.
function maskS2clouds(image) {
  const qa = image.select('QA60');
  // Bits 10 and 11 are clouds and cirrus, respectively.
  const cloudBitMask = 1 << 10;
  const cirrusBitMask = 1 << 11;
  // SCL band (Scene Classification Layer)
  const scl = image.select('SCL');
  // Pixels with values 3 (cloud shadow), 8 (cloud medium probability), 9 (cloud high probability),
  // 10 (cirrus), 11 (snow/ice) are masked.
  const cloudShadowMask = 1 << 3; // Value 3 in SCL is cloud shadow
  const cloudMediumProbMask = 1 << 8; // Value 8 in SCL is cloud medium probability
  const cloudHighProbMask = 1 << 9; // Value 9 in SCL is cloud high probability
  const cirrusSCLMask = 1 << 10; // Value 10 in SCL is cirrus
  const snowIceMask = 1 << 11; // Value 11 in SCL is snow/ice

  // Both QA60 and SCL masks are applied.
  const maskQA = qa.bitwiseAnd(cloudBitMask).eq(0)
             .and(qa.bitwiseAnd(cirrusBitMask).eq(0));

  const maskSCL = scl.neq(3).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10)).and(scl.neq(11));

  return image.updateMask(maskQA.and(maskSCL)).divide(10000); // Scale to SR range [0, 1]
}

// Function to calculate NDVI
function addNDVI(image) {
  const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  return image.addBands(ndvi);
}

async function runAnalysis() {
  const collectionId = 'COPERNICUS/S2_SR';
  const scale = 1000; // Resolution for reduction to avoid memory issues and speed up.

  // 1. Data Acquisition for May 2022
  let may2022 = ee.ImageCollection(collectionId)
                  .filterDate('2022-05-01', '2022-05-31')
                  .filterBounds(geometry);

  const may2022_size = await may2022.size().getInfo();
  if (may2022_size === 0) {
    console.log("No Sentinel-2 images found for May 2022.");
    console.log("C1");
    return;
  }
  console.log(`May 2022 Images: ${may2022_size}`);

  // Apply cloud mask and calculate NDVI
  may2022 = may2022.map(maskS2clouds).map(addNDVI);
  const may_composite = may2022.select('NDVI').median().clip(geometry);

  // 2. Data Acquisition for November 2022
  let nov2022 = ee.ImageCollection(collectionId)
                   .filterDate('2022-11-01', '2022-11-30')
                   .filterBounds(geometry);

  const nov2022_size = await nov2022.size().getInfo();
  if (nov2022_size === 0) {
    console.log("No Sentinel-2 images found for November 2022.");
    console.log("C1");
    return;
  }
  console.log(`Nov 2022 Images: ${nov2022_size}`);

  // Apply cloud mask and calculate NDVI
  nov2022 = nov2022.map(maskS2clouds).map(addNDVI);
  const nov_composite = nov2022.select('NDVI').median().clip(geometry);

  // 3. Validate for valid pixels (C2)
  const may_pixel_count = await may_composite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (may_pixel_count === 0) {
    console.log("No valid pixels for May 2022 after cloud masking.");
    console.log("C2");
    return;
  }

  const nov_pixel_count = await nov_composite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (nov_pixel_count === 0) {
    console.log("No valid pixels for November 2022 after cloud masking.");
    console.log("C2");
    return;
  }

  // 4. Calculate Mean NDVI for both periods
  const may_mean_ndvi_obj = await may_composite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const nov_mean_ndvi_obj = await nov_composite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validate calculation results (C3)
  if (may_mean_ndvi_obj === null || isNaN(may_mean_ndvi_obj) ||
      nov_mean_ndvi_obj === null || isNaN(nov_mean_ndvi_obj)) {
    console.log("NDVI calculation resulted in None/NaN.");
    console.log("C3");
    return;
  }

  const may_mean_ndvi = parseFloat(may_mean_ndvi_obj);
  const nov_mean_ndvi = parseFloat(nov_mean_ndvi_obj);

  console.log(`May 2022 Mean NDVI: ${may_mean_ndvi.toFixed(3)} (Pixels: ${may_pixel_count})`);
  console.log(`Nov 2022 Mean NDVI: ${nov_mean_ndvi.toFixed(3)} (Pixels: ${nov_pixel_count})`);

  // 6. Compare and determine the answer
  if (nov_mean_ndvi > may_mean_ndvi) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
